<?php
require "config.php"; require "auth.php"; requireAdmin();
$id=(int)($_GET['id']??0); $st=$pdo->prepare("SELECT user_id,username,email,created_at FROM users WHERE user_id=? AND role='student'"); $st->execute([$id]); $student=$st->fetch(); if(!$student) die('Student not found.');
$st=$pdo->prepare("SELECT r.*,q.title,q.category FROM results r JOIN quizzes q ON q.quiz_id=r.quiz_id WHERE r.user_id=? ORDER BY r.result_id DESC"); $st->execute([$id]); $results=$st->fetchAll();
?><!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1.0"><title>Student Details - Admin</title><link rel="stylesheet" href="style.css"></head><body><nav class="navbar"><div class="brand">QuizMaster Admin</div><div class="nav-right"><a class="btn small" href="admin_students.php">Students</a><a class="btn small" href="logout.php">Logout</a></div></nav><main class="container"><div class="card"><h1><?= htmlspecialchars($student['username']) ?></h1><p>Email: <?= htmlspecialchars($student['email']) ?></p><p>Joined: <?= htmlspecialchars($student['created_at']) ?></p></div><h2>Complete Quiz History</h2><div class="card"><div class="table-wrap"><table><tr><th>Quiz</th><th>Category</th><th>Score</th><th>Total</th><th>Percentage</th><th>Status</th><th>Date</th></tr><?php foreach($results as $r): ?><tr><td><?= htmlspecialchars($r['title']) ?></td><td><?= htmlspecialchars($r['category']) ?></td><td><?= (int)$r['score'] ?></td><td><?= (int)$r['total_questions'] ?></td><td><?= number_format((float)$r['percentage'],1) ?>%</td><td><?= ((int)$r['score']===0?'0 Marks / Abandoned or Failed':'Completed') ?></td><td><?= htmlspecialchars($r['taken_at']) ?></td></tr><?php endforeach; ?></table></div><?php if(!$results): ?><p class="muted">No attempts yet.</p><?php endif; ?></div></main></body></html>
